from recette_support import *
a=accounts();sender=login_as('member');recipient=login_as('chef');outsider=login_as('admin');d=login_as('director');tag='RECETTE-MESSAGE-'+str(int(time.time()))
sender.post('MessageServlet',dict(destinataire_id=a['chef.id'],contenu=tag+' privé'))
check(tag in recipient.req('messagerie?destinataire_id='+a['member.id'])[1],'message privé visible par destinataire')
check(tag not in outsider.req('messagerie?destinataire_id='+a['member.id'])[1],'message privé absent chez tiers même URL forcée')
mid=db('SELECT id_message FROM message WHERE contenu='+literal(tag+' privé'))
check(outsider.post('MessageServlet',dict(action='lire',id=mid),expect=False)[0]==403,'tiers ne marque pas un message privé comme lu')
recipient.post('MessageServlet',dict(action='lire',id=mid))
check(db('SELECT COUNT(*) FROM lecture_message WHERE message_id='+mid+' AND membre_id='+a['chef.id'])=='1','lecture message persistée destinataire')
sender.post('MessageServlet',dict(equipe_id=a['team.id'],contenu=tag+' équipe'))
check(tag+' équipe' in recipient.req('messagerie?equipe_id='+a['team.id'])[1],'message équipe visible membre équipe')
check(outsider.req('messagerie?equipe_id='+a['team.id'])[0]==403,'conversation équipe refusée à tiers')
check(outsider.post('MessageServlet',dict(equipe_id=a['team.id'],contenu=tag+' intrusion'),expect=False)[0]==403,'écriture équipe refusée à tiers')
state=json.loads((OUT/'mutation-state.json').read_text())
sender.post('MessageServlet',dict(evenement_id=state['event'],contenu=tag+' événement'))
check(tag+' événement' in recipient.req('messagerie?evenement_id='+state['event'])[1],'discussion événement visible entre comptes internes')
code,body,url=d.upload('DocumentServlet',dict(titre=tag+' document',type_doc='RAPPORT'))
check(code==200 and 'Opération enregistrée avec succès.' in body,'document déclenche notifications')
ids={r:db('SELECT id_notif FROM notification WHERE id_membre='+a[r+'.id']+' AND message='+literal('Document ajouté : '+tag+' document')) for r in ['member','chef']}
check(all(ids.values()),'notifications document distinctes pour les deux membres')
recipient_before=recipient.req('notifications')[1]
sender.post('NotificationServlet',dict(id=ids['member']))
check(db('SELECT COUNT(*) FROM notification_lecture WHERE notification_id='+ids['member']+' AND membre_id='+a['member.id'])=='1','notification lue par membre')
check(db('SELECT COUNT(*) FROM notification_lecture WHERE notification_id='+ids['chef'])=='0','notification autre compte reste non lue')
check(sender.post('NotificationServlet',dict(id=ids['chef']),expect=False)[0]==403,'lecture notification autre destinataire interdite')
check(recipient.req('notifications')[1].count('NON LUE')==recipient_before.count('NON LUE'),'badge/état non lu autre compte inchangé')
candidate=db("SELECT id_notif FROM notification WHERE id_membre IS NULL AND message='Nouvelle candidature reçue.' ORDER BY id_notif DESC LIMIT 1")
check(bool(candidate),'notification candidature réelle présente')
check(sender.post('NotificationServlet',dict(id=candidate),expect=False)[0]==403,'notification candidature réservée au directeur')
d.post('NotificationServlet',dict(id=candidate))
check(db('SELECT COUNT(*) FROM notification_lecture WHERE notification_id='+candidate+' AND membre_id=4')=='1','lecture candidature nominative directeur')
save_results('communication')
